//
//  DailyLogItem.swift
//  PersonalOps
//
//  A single timestamped entry on the Daily Log timeline. `content` is raw
//  Markdown; rendering happens in the view layer. `source` distinguishes
//  entries typed by the user from entries injected by the Hermes Agent or
//  generated by the system, so both the UI and the ingestion pipeline can
//  filter/badge them.
//
//  Stored via GRDB (SwiftData's @Model macro is a closed-source macOS-only
//  compiler plugin and cannot build on Linux). `tags` is encoded as a JSON
//  array in a TEXT column by GRDB's Codable record support.
//

import Foundation
import GRDB

enum LogSource: String, Codable, CaseIterable, Sendable {
    case user
    case hermes
    case healthKit = "healthkit"
    case system
}

struct DailyLogItem: Codable, Equatable, Identifiable, Sendable,
    FetchableRecord, PersistableRecord {

    static let databaseTableName = "dailyLogItem"

    var id: UUID
    var timestamp: Date
    /// Markdown body of the entry.
    var content: String
    /// Raw value of `LogSource`, exposed via the computed `source` below.
    var sourceRaw: String
    var tags: [String]
    /// Set true once the Hermes Agent has read/acknowledged this item
    /// (used for items Hermes should react to, e.g. #hermes-tagged notes).
    var processedByHermes: Bool

    var source: LogSource {
        get { LogSource(rawValue: sourceRaw) ?? .user }
        set { sourceRaw = newValue.rawValue }
    }

    /// Start-of-day bucket, convenient for grouping the timeline by day.
    var day: Date {
        Calendar.current.startOfDay(for: timestamp)
    }

    init(
        content: String,
        timestamp: Date = .now,
        source: LogSource = .user,
        tags: [String] = []
    ) {
        self.id = UUID()
        self.timestamp = timestamp
        self.content = content
        self.sourceRaw = source.rawValue
        self.tags = tags
        self.processedByHermes = false
    }
}

extension DailyLogItem {
    enum Columns {
        static let id = Column(CodingKeys.id)
        static let timestamp = Column(CodingKeys.timestamp)
        static let content = Column(CodingKeys.content)
        static let sourceRaw = Column(CodingKeys.sourceRaw)
    }
}
